const recipes = [
  {id:'shakshuka',title:'Füstös shakshuka',type:'Reggeli · húsmentes',time:24,kcal:420,protein:23,match:86,image:'assets/shakshuka.png',tags:['quick','vegetarian','high-protein'],servings:2,ingredients:[['Tojás',4,'db',true],['Paradicsom',500,'g',true],['Kaliforniai paprika',1,'db',true],['Feta',80,'g',false],['Petrezselyem',1,'csokor',true]],description:'Selymes paradicsomos-paprikás alap, lágy tojások és friss zöldfűszerek egyetlen serpenyőben.'},
  {id:'salmon',title:'Citromos lazac',type:'Vacsora · magas fehérje',time:32,kcal:560,protein:42,match:72,image:'assets/salmon.png',tags:['high-protein'],servings:2,ingredients:[['Lazacfilé',300,'g',false],['Spárga',250,'g',true],['Burgonya',400,'g',true],['Citrom',1,'db',true],['Kapor',1,'csokor',false]],description:'Ropogós szélű lazac, zsenge spárga és aranybarna burgonya friss citrommal.'},
  {id:'pasta',title:'Krémes paradicsomos pasta',type:'Ebéd · komfort étel',time:28,kcal:610,protein:24,match:91,image:'assets/hero-pasta.png',tags:['quick','vegetarian'],servings:2,ingredients:[['Rigatoni',220,'g',true],['Koktélparadicsom',350,'g',true],['Tejszín',120,'ml',false],['Parmezán',60,'g',true],['Bazsalikom',1,'csokor',true]],description:'Sült paradicsom, krémes szósz és friss bazsalikom — gyors hétköznapi vacsora, éttermi hangulattal.'},
  {id:'chickpea',title:'Ropogós csicseriborsó tál',type:'Ebéd · növényi',time:20,kcal:480,protein:21,match:78,image:null,tags:['quick','vegetarian'],servings:2,ingredients:[['Csicseriborsó',400,'g',false],['Uborka',1,'db',true],['Paradicsom',2,'db',true],['Tahini',40,'g',false],['Citrom',1,'db',true]],description:'Fűszeres, ropogós és friss tál krémes tahinis öntettel.'},
  {id:'chicken',title:'Mézes-mustáros csirke',type:'Vacsora · családi',time:38,kcal:525,protein:45,match:67,image:null,tags:['high-protein'],servings:4,ingredients:[['Csirkemell',600,'g',false],['Mustár',45,'g',true],['Méz',30,'g',true],['Rizs',300,'g',true],['Brokkoli',400,'g',false]],description:'Szaftos csirkemell kiegyensúlyozott, édeskés-mustáros szósszal.'},
  {id:'soup',title:'Sültpaprika-krémleves',type:'Vacsora · húsmentes',time:45,kcal:330,protein:12,match:83,image:null,tags:['vegetarian'],servings:4,ingredients:[['Kaliforniai paprika',5,'db',true],['Paradicsom',3,'db',true],['Zöldségalaplé',700,'ml',false],['Tejszín',100,'ml',false],['Kenyér',4,'szelet',true]],description:'Intenzív, selymes leves ropogós kenyérrel és egy kevés füstös paprikával.'}
];

const defaultPantry = [
  {id:1,name:'Paradicsom',qty:6,unit:'db',category:'Zöldség és gyümölcs'},
  {id:2,name:'Citrom',qty:2,unit:'db',category:'Zöldség és gyümölcs'},
  {id:3,name:'Bazsalikom',qty:1,unit:'csokor',category:'Zöldség és gyümölcs'},
  {id:4,name:'Tojás',qty:8,unit:'db',category:'Hűtő'},
  {id:5,name:'Parmezán',qty:120,unit:'g',category:'Hűtő'},
  {id:6,name:'Rigatoni',qty:500,unit:'g',category:'Szárazáru'},
  {id:7,name:'Rizs',qty:800,unit:'g',category:'Szárazáru'},
  {id:8,name:'Füstölt paprika',qty:null,unit:'',category:'Fűszerek'}
];
const defaultShopping=[
  {id:1,name:'Lazacfilé',qty:'300 g',source:'Citromos lazac',bought:false},
  {id:2,name:'Spárga',qty:'250 g',source:'Citromos lazac',bought:false},
  {id:3,name:'Feta',qty:'80 g',source:'Füstös shakshuka',bought:true}
];

const store={
  get(key,fallback){try{return JSON.parse(localStorage.getItem(`secondchef-${key}`))??fallback}catch{return fallback}},
  set(key,value){localStorage.setItem(`secondchef-${key}`,JSON.stringify(value))}
};
let favorites=store.get('favorites',['pasta']);
let pantry=store.get('pantry',defaultPantry);
let shopping=store.get('shopping',defaultShopping);
let currentFilter='all';
let toastTimer;

const $=(s,ctx=document)=>ctx.querySelector(s);const $$=(s,ctx=document)=>[...ctx.querySelectorAll(s)];
const icons={discover:'✦',pantry:'▦',favorites:'♡',shopping:'✓',profile:'◉'};
const navItems=[['discover','Felfedezés'],['pantry','Kamrám'],['favorites','Kedvencek'],['shopping','Lista'],['profile','Profil']];

function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2400)}
function activeRoute(){return location.hash.replace('#','')||'home'}
function renderAppNav(){$$('[data-app-nav]').forEach(nav=>{nav.innerHTML=navItems.map(([r,n])=>`<a href="#${r}" data-nav="${r}"><span>${icons[r]}</span>${n}</a>`).join('')})}
function route(){const name=activeRoute();const valid=$(`[data-route="${name}"]`)?name:'home';$$('.page-view').forEach(v=>v.classList.toggle('active',v.dataset.route===valid));$$('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===valid));$$('#mobileAppNav a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')===`#${valid}`));const appMode=valid!=='home';$('#siteHeader').classList.toggle('app-mode',appMode);$('#mobileAppNav').classList.toggle('show',appMode);closeMenu();window.scrollTo({top:0,behavior:'instant'});if(valid==='discover')renderDiscover();if(valid==='pantry')renderPantry();if(valid==='favorites')renderFavorites();if(valid==='shopping')renderShopping()}

function cardMarkup(r){const saved=favorites.includes(r.id);return `<article class="recipe-card" data-recipe="${r.id}" tabindex="0" aria-label="${r.title} recept megnyitása"><button class="heart-button ${saved?'saved':''}" data-heart="${r.id}" aria-label="${saved?'Eltávolítás a kedvencekből':'Mentés a kedvencekhez'}">${saved?'♥':'♡'}</button><div class="image-wrap ${r.image?'':'placeholder'}">${r.image?`<img src="${r.image}" alt="${r.title}" />`:`<span>${r.title.charAt(0)}</span>`}<div class="match-chip">${r.match}% egyezés</div></div><div class="recipe-body"><div class="recipe-topline"><span>${r.type}</span><span>${r.time} perc</span></div><h3>${r.title}</h3><div class="recipe-meta"><span>${r.kcal} kcal</span><span>${r.protein} g fehérje</span><span>${r.servings} adag</span></div></div></article>`}
function bindCards(ctx=document){$$('.recipe-card',ctx).forEach(card=>{card.addEventListener('click',e=>{if(e.target.closest('[data-heart]'))return;openRecipe(card.dataset.recipe)});card.addEventListener('keydown',e=>{if(e.key==='Enter')openRecipe(card.dataset.recipe)})});$$('[data-heart]',ctx).forEach(btn=>btn.addEventListener('click',e=>{e.stopPropagation();toggleFavorite(btn.dataset.heart)}))}
function renderHomeCards(){const el=$('#homeRecipeRail');el.innerHTML=recipes.slice(0,3).map(cardMarkup).join('');bindCards(el)}
function renderDiscover(){const list=currentFilter==='all'?recipes:recipes.filter(r=>r.tags.includes(currentFilter));const grid=$('#discoverGrid');grid.innerHTML=list.map(cardMarkup).join('');bindCards(grid)}
function renderFavorites(){const list=recipes.filter(r=>favorites.includes(r.id));const grid=$('#favoritesGrid');grid.innerHTML=list.length?list.map(cardMarkup).join(''):`<div class="empty-state"><span>♡</span><h2>Még nincs itt semmi.</h2><p>Ments el egy receptet a Felfedezés oldalon.</p><a class="pill-button coral" href="#discover">Receptek felfedezése</a></div>`;bindCards(grid)}
function toggleFavorite(id){favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];store.set('favorites',favorites);toast(favorites.includes(id)?'Recept elmentve':'Eltávolítva a kedvencekből');renderHomeCards();if(activeRoute()==='discover')renderDiscover();if(activeRoute()==='favorites')renderFavorites();const modalHeart=$('#modalHeart');if(modalHeart&&modalHeart.dataset.id===id){modalHeart.textContent=favorites.includes(id)?'♥ Mentve':'♡ Mentés'}}

function openRecipe(id){const r=recipes.find(x=>x.id===id);if(!r)return;let servings=r.servings;const dialog=$('#recipeModal');function content(){const factor=servings/r.servings;$('#recipeModalContent').innerHTML=`<div class="recipe-modal-grid"><div class="recipe-modal-image">${r.image?`<img src="${r.image}" alt="${r.title}" />`:`<div class="image-wrap placeholder"><span>${r.title[0]}</span></div>`}</div><div class="recipe-modal-copy"><p class="eyebrow">${r.type}</p><h2>${r.title}</h2><p>${r.description}</p><div class="modal-meta"><span>◷ ${r.time} perc</span><span>◉ ${Math.round(r.kcal*factor)} kcal / adag</span><span>● ${r.protein} g fehérje</span></div><div class="serving-control"><span>Adagok száma</span><div><button id="minusServing" aria-label="Adag csökkentése">−</button><strong>${servings}</strong><button id="plusServing" aria-label="Adag növelése">+</button></div></div><ul class="ingredients">${r.ingredients.map(([n,q,u,has])=>`<li><span>${has?'●':'○'} ${n}</span><strong>${Number((q*factor).toFixed(1))} ${u}</strong></li>`).join('')}</ul><p class="safety-note">● megvan a kamrában · ○ hiányzik vagy a mennyiség nem ellenőrizhető</p><div class="modal-actions"><button class="pill-button coral" id="modalShopping">Hiányzók a listára</button><button class="subtle-button" id="modalHeart" data-id="${r.id}">${favorites.includes(r.id)?'♥ Mentve':'♡ Mentés'}</button></div></div></div>`;$('#minusServing').onclick=()=>{if(servings>1){servings--;content()}};$('#plusServing').onclick=()=>{if(servings<20){servings++;content()}};$('#modalHeart').onclick=()=>toggleFavorite(r.id);$('#modalShopping').onclick=()=>addMissing(r,servings/r.servings)}content();dialog.showModal()}
function addMissing(r,factor=1){const missing=r.ingredients.filter(x=>!x[3]);let added=0;missing.forEach(([name,qty,unit])=>{if(!shopping.some(i=>i.name===name&&!i.bought)){shopping.push({id:Date.now()+added,name,qty:`${Number((qty*factor).toFixed(1))} ${unit}`,source:r.title,bought:false});added++}});store.set('shopping',shopping);toast(added?`${added} tétel a bevásárlólistán`:'Ezek már a listán vannak')}

function renderPantry(query=''){const filtered=pantry.filter(i=>i.name.toLowerCase().includes(query.toLowerCase()));const grouped=Object.groupBy?Object.groupBy(filtered,i=>i.category):filtered.reduce((a,i)=>((a[i.category]??=[]).push(i),a),{});$('#pantryCount').textContent=pantry.length;const el=$('#pantryGroups');el.innerHTML=Object.entries(grouped).map(([cat,items])=>`<section class="pantry-group"><h2>${cat}</h2>${items.map(i=>`<div class="pantry-item"><div><strong>${i.name}</strong><small>${i.qty==null?'Mennyiség nincs megadva':'Készleten'}</small></div><span>${i.qty??'—'} ${i.unit}</span><button data-remove-pantry="${i.id}" aria-label="${i.name} törlése">×</button></div>`).join('')}</section>`).join('')||`<div class="empty-state"><span>⌕</span><h2>Nincs találat.</h2><p>Próbálj más kifejezést.</p></div>`;$$('[data-remove-pantry]').forEach(b=>b.onclick=()=>{pantry=pantry.filter(i=>i.id!==Number(b.dataset.removePantry));store.set('pantry',pantry);renderPantry($('#pantrySearch').value);toast('Alapanyag eltávolítva')})}
function renderShopping(){const el=$('#shoppingList');el.innerHTML=shopping.length?shopping.map(i=>`<div class="shopping-row ${i.bought?'bought':''}"><input type="checkbox" data-check-shopping="${i.id}" ${i.bought?'checked':''} aria-label="${i.name} megjelölése"/><div><strong>${i.name}</strong><small>${i.source||'Kézzel hozzáadva'}</small></div><span>${i.qty||''}</span><button data-remove-shopping="${i.id}" aria-label="${i.name} törlése">×</button></div>`).join(''):`<div class="empty-state"><span>✓</span><h2>A listád üres.</h2><p>Minden megvan a következő főzéshez.</p></div>`;$$('[data-check-shopping]').forEach(c=>c.onchange=()=>{const item=shopping.find(i=>i.id===Number(c.dataset.checkShopping));item.bought=c.checked;store.set('shopping',shopping);renderShopping()});$$('[data-remove-shopping]').forEach(b=>b.onclick=()=>{shopping=shopping.filter(i=>i.id!==Number(b.dataset.removeShopping));store.set('shopping',shopping);renderShopping()})}

function closeMenu(){document.body.classList.remove('menu-open');$('#mobileMenu').classList.remove('open');$('#mobileMenu').setAttribute('aria-hidden','true');$('#menuButton').setAttribute('aria-expanded','false')}
function initInteractions(){
  $('#menuButton').onclick=()=>{const open=!$('#mobileMenu').classList.contains('open');document.body.classList.toggle('menu-open',open);$('#mobileMenu').classList.toggle('open',open);$('#mobileMenu').setAttribute('aria-hidden',String(!open));$('#menuButton').setAttribute('aria-expanded',String(open))};$$('#mobileMenu a').forEach(a=>a.onclick=closeMenu);
  $('#searchToggle').onclick=()=>{document.body.classList.add('search-open');$('#searchOverlay').classList.add('open');$('#searchOverlay').setAttribute('aria-hidden','false');setTimeout(()=>$('#globalSearch').focus(),300)};$('#closeSearch').onclick=closeSearch;function closeSearch(){document.body.classList.remove('search-open');$('#searchOverlay').classList.remove('open');$('#searchOverlay').setAttribute('aria-hidden','true')}
  const suggestions=['Gyors vacsora','Magas fehérje','Paradicsom','Lazac'];$('#searchSuggestions').innerHTML=suggestions.map(s=>`<button>${s}</button>`).join('');$$('#searchSuggestions button').forEach(b=>b.onclick=()=>{$('#globalSearch').value=b.textContent;performSearch(b.textContent)});$('#globalSearch').addEventListener('keydown',e=>{if(e.key==='Enter')performSearch(e.target.value)});function performSearch(q){closeSearch();location.hash='discover';setTimeout(()=>{const term=q.toLowerCase();currentFilter=term.includes('fehérje')?'high-protein':term.includes('gyors')?'quick':'all';$$('.quick-filters button').forEach(b=>b.classList.toggle('active',b.dataset.filter===currentFilter));renderDiscover();toast(`Találatok: ${q}`)},150)}
  $$('.quick-filters button').forEach(b=>b.onclick=()=>{currentFilter=b.dataset.filter;$$('.quick-filters button').forEach(x=>x.classList.toggle('active',x===b));renderDiscover()});
  $('#addPantryButton').onclick=()=>$('#pantryModal').showModal();$('#pantrySearch').oninput=e=>renderPantry(e.target.value);$('#photoDemo').onclick=()=>toast('A fotófelismerés demóban kézi jóváhagyással működne.');
  $('#pantryForm').onsubmit=e=>{e.preventDefault();pantry.push({id:Date.now(),name:$('#pantryName').value.trim(),qty:$('#pantryQty').value?Number($('#pantryQty').value):null,unit:$('#pantryUnit').value,category:$('#pantryCategory').value});store.set('pantry',pantry);e.target.reset();$('#pantryModal').close();renderPantry();toast('Alapanyag hozzáadva')};
  $('#shoppingForm').onsubmit=e=>{e.preventDefault();shopping.push({id:Date.now(),name:$('#shoppingInput').value.trim(),qty:$('#shoppingQuantity').value.trim(),source:'Kézzel hozzáadva',bought:false});store.set('shopping',shopping);e.target.reset();renderShopping();toast('Tétel hozzáadva')};$('#clearBought').onclick=()=>{const n=shopping.filter(i=>i.bought).length;shopping=shopping.filter(i=>!i.bought);store.set('shopping',shopping);renderShopping();toast(n?`${n} megvett tétel törölve`:'Nincs megvett tétel')};
  $$('.modal-close').forEach(b=>b.onclick=()=>b.closest('dialog').close());$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d)d.close()}));
  $$('#dietChoices button').forEach(b=>b.onclick=()=>{$$('#dietChoices button').forEach(x=>x.classList.remove('active'));b.classList.add('active')});$$('#allergyChoices button').forEach(b=>b.onclick=()=>b.classList.toggle('active'));$('#saveProfile').onclick=()=>toast('Beállítások elmentve');
}

function initMotion(){
  const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
  const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)e.target.classList.add('visible')}),{threshold:.12});$$('.reveal').forEach(el=>observer.observe(el));
  const hero=$('#hero'),img=$('.hero-image');if(!reduce)hero.addEventListener('pointermove',e=>{const x=(e.clientX/innerWidth-.5)*12,y=(e.clientY/innerHeight-.5)*8;img.style.transform=`scale(1.08) translate(${x}px,${y}px)`});
  const story=$('#scrollStory'),plate=$('.plate-wrap');function onScroll(){const max=document.documentElement.scrollHeight-innerHeight;$('.scroll-progress').style.width=`${max?scrollY/max*100:0}%`;const rect=story.getBoundingClientRect(),progress=Math.max(0,Math.min(1,-rect.top/(story.offsetHeight-innerHeight)));const step=Math.min(2,Math.floor(progress*3));$$('.story-step').forEach((el,i)=>el.classList.toggle('active',i===step));$$('.story-dots i').forEach((el,i)=>el.classList.toggle('active',i===step));if(!reduce)plate.style.transform=`rotate(${progress*210-20}deg) scale(${.9+progress*.13})`;if(!reduce&&activeRoute()==='home')img.style.transform=`scale(${1.06+Math.min(scrollY/5000,.05)}) translateY(${Math.min(scrollY*.08,45)}px)`}addEventListener('scroll',onScroll,{passive:true});onScroll()
}

renderAppNav();renderHomeCards();renderDiscover();renderPantry();renderFavorites();renderShopping();initInteractions();initMotion();addEventListener('hashchange',route);route();
